using System;
using System.Collections.Generic;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace Azure.ResourceManager
{
    internal class AotSafeResponseErrorConverter : JsonConverter<ResponseError>
    {
        public override ResponseError Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            using var doc = JsonDocument.ParseValue(ref reader);
            return ReadResponseError(doc.RootElement);
        }

        public override void Write(Utf8JsonWriter writer, ResponseError value, JsonSerializerOptions options)
        {
            WriteResponseError(writer, value);
        }

        private static ResponseError ReadResponseError(JsonElement element)
        {
            if (element.ValueKind == JsonValueKind.Null)
                return null;

            string code = null;
            string message = null;
            string target = null;
            JsonElement additionalInfo = default;
            ResponseInnerError innerError = null;
            List<ResponseError> details = null;

            foreach (var property in element.EnumerateObject())
            {
                switch (property.Name)
                {
                    case "code":
                        code = property.Value.GetString();
                        break;
                    case "message":
                        message = property.Value.GetString();
                        break;
                    case "target":
                        target = property.Value.GetString();
                        break;
                    case "innererror":
                        innerError = ReadResponseInnerError(property.Value);
                        break;
                    case "details":
                        details = new List<ResponseError>();
                        foreach (var item in property.Value.EnumerateArray())
                        {
                            details.Add(ReadResponseError(item));
                        }
                        break;
                    case "additionalInfo":
                        additionalInfo = property.Value.Clone();
                        break;
                }
            }

            return new ResponseError(code, message, target, additionalInfo, innerError, details);
        }

        private static ResponseInnerError ReadResponseInnerError(JsonElement element)
        {
            if (element.ValueKind == JsonValueKind.Null)
                return null;

            string code = null;
            ResponseInnerError innerError = null;

            foreach (var property in element.EnumerateObject())
            {
                switch (property.Name)
                {
                    case "code":
                        code = property.Value.GetString();
                        break;
                    case "innererror":
                        innerError = ReadResponseInnerError(property.Value);
                        break;
                }
            }

            return new ResponseInnerError(code, innerError);
        }

        private static void WriteResponseError(Utf8JsonWriter writer, ResponseError value)
        {
            if (value == null)
            {
                writer.WriteNullValue();
                return;
            }

            writer.WriteStartObject();

            if (value.Code != null)
            {
                writer.WriteString("code"u8, value.Code);
            }

            if (value.Message != null)
            {
                writer.WriteString("message"u8, value.Message);
            }

            if (value.Target != null)
            {
                writer.WriteString("target"u8, value.Target);
            }

            if (value.InnerError != null)
            {
                writer.WritePropertyName("innererror"u8);
                WriteResponseInnerError(writer, value.InnerError);
            }

            if (value.Details != null && value.Details.Count > 0)
            {
                writer.WritePropertyName("details"u8);
                writer.WriteStartArray();
                foreach (var detail in value.Details)
                {
                    WriteResponseError(writer, detail);
                }
                writer.WriteEndArray();
            }

            writer.WriteEndObject();
        }

        private static void WriteResponseInnerError(Utf8JsonWriter writer, ResponseInnerError value)
        {
            if (value == null)
            {
                writer.WriteNullValue();
                return;
            }

            writer.WriteStartObject();

            if (value.Code != null)
            {
                writer.WriteString("code"u8, value.Code);
            }

            if (value.InnerError != null)
            {
                writer.WritePropertyName("innererror"u8);
                WriteResponseInnerError(writer, value.InnerError);
            }

            writer.WriteEndObject();
        }
    }
